mapper.select:
SELECT e.id, e.serial_number, e.patient_id, p.name AS patient_name, p.gender, TIMESTAMPDIFF(YEAR, p.birth_date, CURDATE()) AS age, p.phone AS phone_number, p.disease_type, e.followup_plan_id, pl.plan_name AS followup_plan_name, e.followup_project_id, pm.project_name AS followup_project, e.followup_team, e.primary_doctor, e.health_manager, e.application_time, e.enrollment_time, e.followup_status, e.enrollment_remark, e.created_time, e.updated_time, e.created_by, e.updated_by FROM followup_patient_enrollment e LEFT JOIN patient p ON e.patient_id = p.id LEFT JOIN followup_plan_repository pl ON e.followup_plan_id = pl.id LEFT JOIN followup_program_master pm ON e.followup_project_id = pm.id
AND p.name LIKE CONCAT('%', #{query.patientName}, '%')
AND e.application_time >= #{query.applicationStartTime}
AND e.application_time <= #{query.applicationEndTime}
AND e.enrollment_time >= #{query.enrollmentStartTime}
AND e.enrollment_time <= #{query.enrollmentEndTime}
AND TIMESTAMPDIFF(YEAR, p.birth_date, CURDATE()) BETWEEN 0 AND 17
AND TIMESTAMPDIFF(YEAR, p.birth_date, CURDATE()) BETWEEN 18 AND 30
AND TIMESTAMPDIFF(YEAR, p.birth_date, CURDATE()) BETWEEN 31 AND 50
AND TIMESTAMPDIFF(YEAR, p.birth_date, CURDATE()) BETWEEN 51 AND 70
AND TIMESTAMPDIFF(YEAR, p.birth_date, CURDATE()) > 70
AND pl.plan_name = #{query.followupPlanName}
AND e.followup_status = #{query.followupStatus}
ORDER BY e.application_time DESC
